// План: specs/disputes.md, блок 3. Кейс: .qa/tests/disputes/DSP-007.
// Несколько ролей: клиент открывает спор с בורר אנושי, נותן שירות отказывается.
// Создаёт сделку QA-AUTO-… → не @prod-safe. Деньги остаются в נאמנות — id в qa-auto-created.jsonl для чистки.
import { test, expect } from '../../fixtures';
import { getEscrowDeal, openArbiterDispute, openTab, waitWithReload, historyEntries, TODAY_TIME, CLIENT_NAME, PROVIDER_NAME } from './helpers';

test.describe.configure({ retries: 0 });

test.describe('מחלוקות — בורר אנושי נדחה', () => {
  test('בורר אנושי נדחה: ביומן "נסגרה ללא הכרעה על ידי שירה כהן" בלי "הוכרעה" @android #45354c82', async ({ asUser }) => {
    const client = await asUser('client');
    const provider = await asUser('provider');
    const { id } = await getEscrowDeal(client, provider, 'ARBITER');

    await openArbiterDispute(client, id);

    // Поставщик видит запрос клиента и отказывается.
    await provider.goto(`/deals/${id}?tab=dispute`);
    await waitWithReload(provider, provider.getByText('האם את/ה מאשר גישור בעזרת בורר אנושי?'));
    await provider.getByRole('button', { name: 'דחייה', exact: true }).click();

    const closed = 'המחלוקת נסגרה ללא הכרעה';
    const closedBy = `המחלוקת נסגרה ללא הכרעה על ידי ${PROVIDER_NAME}`;

    for (const [who, page] of [['provider', provider], ['client', client]] as const) {
      // Вкладка «מחלוקת»: закрыто без решения (у обеих сторон).
      await page.goto(`/deals/${id}?tab=dispute`);
      await waitWithReload(page, page.getByText(closed, { exact: true }));

      // «היסטוריה»: запись соответствует событию, со временем; «הוכרעה» нет.
      await openTab(page, 'היסטוריה');
      await waitWithReload(page, page.getByText(closedBy, { exact: true }));
      const entries = await historyEntries(page);
      expect(entries[0], who).toBe(closedBy);
      expect(entries[1], who).toMatch(TODAY_TIME);
      expect(entries[2], who).toBe(`נפתחה מחלוקת על ידי ${CLIENT_NAME}`);
      const all = entries.join('\n');
      expect(all, who).not.toContain('המחלוקת הוכרעה');
      expect(all, who).toContain('הכסף התקבל ונשמר ב-SafePay');
      expect(all, who).toContain(`העסקה אושרה על ידי ${PROVIDER_NAME}`);
      expect(all, who).toContain('העסקה נוצרה');
    }
  });
});
